    int key = entry.key!;
    double value = entry.value;

    sumMap.remove(key);

    if (value.abs() <= 1e-9) continue;

    int sign = value > 0 ? 1 : -1;
    double targetValue = abs(value);

    double r = sqrt(targetValue / (key.toDouble()));
    double c = (targetValue / r - key.toDouble()) / 2.0;

    int newKeyA = (c >= 0 ? ceil(c) : floor(c));
    int newKeyB = (newKeyA + 1);

    if (newKeyA >= 1 && newKeyA <= n && 
        newKeyB >= 1 && newKeyB <= n && 
        newKeyA != newKeyB) {

      // Add the pair to sumMap with opposite signs
      sumMap[newKeyA] = sumMap.get(newKeyA)?.abs() ?? 0.0;
