  List<Point> getInitialHull(List<Point> points) {
    if (points.isEmpty) return [];

    // Sort the points by x-coordinate, then y-coordinate.
    points.sort((a, b) => a.x == b.x ? a.y.compareTo(b.y) : a.x.compareTo(b.x));

    final lower = <Point>[];

