List<List<Point>> prepareConvexHulls(List<Point> points) {
  if (points.isEmpty || points.length < 3) return [];

  // Sort points by x-coordinate, and then by y-coordinate for ties.
  List<Point> sortedPoints = [...points]..sort((a, b) => a.x == b.x ? a.y.compareTo(b.y) : a.x.compareTo(b.x));

  // Build lower hull.
  List<Point> lower = [];
  for (Point p in sortedPoints) {
    while (lower.length >= 2 && _cross(lower[lower.length - 1], lower[lower.length - 2], p) <= 0) {
      lower.removeLast();
    }
    lower.add(p);
  }

  // Build upper hull.
  List<Point> upper = [sortedPoints.last];
  for (int i = sortedPoints.length - 2; i >= 0; i--) {
    Point p = sortedPoints[i];
    while (upper.length >= 2 && _cross(upper[upper.length - 1], upper[upper.length - 2], p) <= 0) {
      upper.removeLast();
    }
    upper.add(p);
  }

  // Combine lower and upper hulls to form the convex hull.
  // Ensure no duplicate endpoints are added.
  List<Point> combinedHull = lower.sublist(0, lower.length - 1)..addAll(upper.sublist(0, upper.length - 1));

  return [combinedHull];
}


bool _cross(Point o, Point a, Point b) {
  double crossProduct = (a.x - o.x) * (b.y - o.y) - (a.y - o.y) * (b.x - o.x);
  return crossProduct > 0; // For counter-clockwise orientation
}

