bool compareX(const Point &a, const Point &b) { return a.x < b.x; }

double crossProduct(Point o, Point a, Point b) {
    return (a.x - o.x) * (b.y - o.y) - (a.y - o.y) * (b.x - o.x);
}

vector<Point> convexHull(vector<Point> points) {
    sort(points.begin(), points.end(), compareX);

    vector<Point> hull(2 * points.size());
    int k = 0;

    for (int i = 0; i < points.size(); ++i) {
        while (k > 1 && crossProduct(hull[k - 2], hull[k - 1], points[i]) <= 0) --k;
        hull[k++] = points[i];
    }

    int t = k + 1;
    for (int i = points.size() - 2; i >= 0; --i) {
        while (k > t && crossProduct(hull[k - 2], hull[k - 1], points[i]) <= 0) --k;
        hull[k++] = points[i];
    }

    hull.resize(k - 1);
    return hull;
}

