}

import 'dart:math';

class SetBase {
  List<int> _elements;

  SetBase(this._elements);

  void add(int element) {
    if (!_elements.contains(element)) {
      _elements.add(element);
    }
  }

  bool contains(int element) => _elements.contains(element);

  int get size => _elements.length;

  static SetBase intersection(SetBase a, SetBase b) {
    var result = SetBase([]);
    for (var e in a._elements) {
      if (b.contains(e)) {
        result.add(e);
      }
    }
    return result;
  }

  static SetBase union(SetBase a, SetBase b) {
    var result = SetBase([...a._elements]);
    for (var e in b._elements) {
      result.add(e);
    }
    return result;
  }
}

