void tonelliShanks(int n, int p) {
  if (p == 2 || p % 4 == 3) {
    // Handle special cases for small primes or when p ≡ 3 mod 4.
    print((n).pow(1 / 2));
    return;
  } else {
    // General Tonelli-Shanks algorithm implementation goes here.
    List<int> factors = [];
    var q = p - 1;

    while ((q & 1) != 0) {
      factors.add(q);
      q >>= 1;
    }

    var z = _findPrimitiveRoot(p);
    var c = pow(z, factors[0], p);

    var t = pow(n, q, p);
    var m = factors.length;
    var i = 0;

    while (t != 1 && i < m) {
      int temp = t;
      while (temp != 1) {
        temp = pow(temp, 2, p);
      }

      var j = m - i - 1;
      var b = pow(c, pow(2, j), p);

      x = multiply(x, b, p);
      c = multiply(b, b, p);
      t = multiply(t, c, p);
      i++;
    }

    if (x * x % p == n) {
      print("Solution found: $x");
    } else {
      print("No solution exists.");
    }
  }
}

