class ShuntingYard {
  static List<String> toPostfix(List<String> infixTokens, Map<String, dynamic> precedenceMap) {
    final Stack<String> operatorsStack = [];
    final List<String> outputQueue = [];

    for (final token in infixTokens) {
      if (_isNumber(token)) {
        outputQueue.add(token);
      } else if (_isOperator(token)) {
        while (operatorsStack.isNotEmpty && _shouldPop(operator, token, precedenceMap)) {
          outputQueue.add(operatorsStack.removeLast());
        }
        operatorsStack.add(token);
      } else if (token == '(') {
        operatorsStack.add(token);
      } else if (token == ')') {
        while (operatorsStack.isNotEmpty && operatorsStack.last != '(') {
          outputQueue.add(operatorsStack.removeLast());
        }
        if (operatorsStack.isEmpty || operatorsStack.first != '(') throw Exception('Mismatched parentheses');
        operatorsStack.removeLast(); // Remove the opening parenthesis
      }
    }

    while (operatorsStack.isNotEmpty) {
      final operator = operatorsStack.removeLast();
      if (operator == '(') throw Exception('Unmatched left parenthesis');
      outputQueue.add(operator);
    }

    return outputQueue;
  }

  static bool _isNumber(String token) => int.tryParse(token) != null;
  static bool _isOperator(String token) => ['+', '-', '*', '/', '(', ')'].contains(token);

  static bool _shouldPop(String topOfStack, String currentToken, Map<String, dynamic> precMap) {
    if (!precMap.containsKey(topOfStack)) return false; 
    if (!precMap.containsKey(currentToken)) return false; 

    final currentPrec = int.parse(precMap[currentToken]);
    final stackPrec = int.parse(precMap[topOfStack]);

    if (stackPrec >= currentPrec && isLeftAssociative(topOfStack)) return true;
    return false;
  }
}

