class Fp2 {
  final int x;
  final int y;

  Fp2(this.x, this.y);

  static const k = BigInt.parse('1085749'); // Example modulus for finite field GF(2^k)

  @override
  String toString() => '$x + $y * w';

  Fp2 multiply(Fp2 other) {
    if (other == Fp2.zero) return Fp2.zero;

    int a = other.x % k;
    int b = other.y % k;

    int c = ((a * x) % k + (b * y) % k) % k;
    int d = (((-c) % k + k) % k + ((x * y) % k)) % k;

    return Fp2(c.toInt(), d.toInt());
  }

  factory Fp2.fromBigInt(BigInt bigIntValue) {
    BigInt a = bigIntValue / BigInt.pow(k, BigInt.one);
    BigInt b = bigIntValue % k;

    return Fp2(a.toInt(), b.toInt());
  }

  factory Fp2.fromHex(String hexString) {
    BigInt value = BigInt.parse(hexString, radix: 16);
    return Fp2.fromBigInt(value);
  }

  static const zero = Fp2(0, 0);
}

